from lib import *
S = SS('w103')
steps = [
    step("RFC 3164(传统 BSD syslog)的报文是 <PRI>标签[进程号]: 消息。用 Python 的 SysLogHandler 发 4 条不同设施 / 级别的日志,接收端是本机一个 UDP 套接字:<36>w103app[30057]: sample warning message → PRI 36 = 设施 auth(4)× 8 + 级别 warning(4);<30>… info → 30 = daemon(3)× 8 + info(6);<131>… error → 131 = local0(16)× 8 + err(3);<23>… debug → 23 = mail(2)× 8 + debug(7)。PRI = 设施 × 8 + 级别,级别数值越小越严重(0 emerg … 7 debug)。每条报文末尾带一个 NUL 字节(Python 的 SysLogHandler 加的)。这种传统格式里没有时间戳和主机名(Python 的 SysLogHandler 不写),接收端只能用“收到的时间”和“发送方的 IP”补上,发送方的时间与身份无法验证。", t=tl(S(1)), mark=lidx(S(1), "b'<36>", "b'<131>"), done=lidx(S(1), "b'<30>", "b'<23>", '原始报文'), kv=KV([['<36>', 'auth(4)× 8 + warning(4)'], ['<30>', 'daemon(3)× 8 + info(6)'], ['<131>', 'local0(16)× 8 + err(3)'], ['<23>', 'mail(2)× 8 + debug(7)']], ['<36>'])),
    step("RFC 5424(现代 syslog)的格式:<PRI>版本 时间戳 主机名 应用名 进程号 消息ID [结构化数据] 消息。手工拼的例子:<165>1 2026-10-15T12:34:56.789Z host1.example.net w103app 4321 ID47 [exampleSDID@32473 iut=\"3\" eventSource=\"Application\" eventID=\"1011\"] An application event log entry。解析:PRI 165 = 设施 local4(20)× 8 + 级别 notice(5);版本 1;时间戳 ISO 8601,带时区和毫秒;主机名、应用名、进程号、消息 ID 各占一个字段(没有就写 -);结构化数据 [ID k=\"v\" …];最后才是消息。5424 把时间戳、主机名、应用名放进了格式本身,并增加了结构化数据,比 3164 更容易被机器解析。", t=tl(S(2)), mark=lidx(S(2), '原文', '解析'), done=lidx(S(2), '5424 把时间戳'), kv=KV([['PRI 165', 'local4(20)× 8 + notice(5)'], ['时间戳', 'ISO 8601,带毫秒和时区'], ['结构化数据', '[ID k="v" …]']], ['结构化数据'])),
    step("UDP syslog 没有任何送达保证。lo0 上用 netlab 加丢包(每方向),发送端发 500 条:0% 丢包 → UDP 收到 500 条,TCP 收到 500 条;10% 丢包 → UDP 只收到 456 条(丢了 44 条,8.8%),TCP 500 条;30% 丢包 → UDP 收到 358 条(丢了 142 条,28.4%),TCP 仍然 500 条一条没丢(TCP 在底下重传了,代价是延迟)。发送端对 UDP 丢失完全不知道:syslog 没有确认机制,而网络不稳时恰恰是日志最重要的时候。", t=tl(S(3)), mark=lidx(S(3), '丢包 10%', '丢包 30%'), done=lidx(S(3), '丢包  0%', 'UDP 丢的包'), b=bars([['10% 丢包 UDP 收到', 456, '456 / 500'], ['30% 丢包 UDP 收到', 358, '358 / 500'], ['任何丢包 TCP 收到', 500, '500 / 500']], 500, mark=[0, 1], done=[2]), kv=KV([['10% 丢包', 'UDP 丢 44 条(8.8%),TCP 丢 0'], ['30% 丢包', 'UDP 丢 142 条(28.4%),TCP 丢 0'], ['发送端', 'UDP 丢失毫无察觉']], ['30% 丢包'])),
    step("接收端来不及处理也会丢。发送端 0.14 秒一口气发完 20000 条(每条约 60 字节),接收端每条处理约 0.5 ms(代码里 sleep 0.0005 秒):默认缓冲区下只收到 4064 条,丢了 15936 条(79.7%);把 SO_RCVBUF 设成 8 KiB,只收到 262 条,丢了 19738 条(98.7%)。UDP 发送端不会因为接收端缓冲区满而放慢,丢掉的包没有任何通知。突发日志(比如故障时)最容易触发这种丢失。", t=tl(S(4)), mark=lidx(S(4), '默认缓冲区', 'SO_RCVBUF = 8 KiB'), done=lidx(S(4), '默认缓冲区'), b=bars([['默认缓冲区 收到', 4064, '4064 / 20000'], ['8 KiB 缓冲区 收到', 262, '262 / 20000']], 20000, mark=[1], done=[0]), kv=KV([['默认缓冲区', '收到 4064 条,丢 79.7%'], ['SO_RCVBUF 8 KiB', '收到 262 条,丢 98.7%']], ['SO_RCVBUF 8 KiB'])),
    step("没有认证:任何能把 UDP 包送到 514 端口的人都能伪造日志。我向本机的接收套接字发了一条 “<38>Oct 15 12:00:00 victim-host sshd[999]: Accepted password for root from 203.0.113.9 port 51234 ssh2”,接收端照单全收,看上去就是一条登录成功的日志——但它完全是我伪造的(没有任何 sshd,主机名和地址都是我写的)。接收端只能看到来源 IP,而 UDP 的源 IP 也可以伪造,所以内容的真实性无法验证;这就是审计日志需要 TLS 传输加签名,或者先放进可信的本机再转发的原因。(这只是向我自己的接收套接字发了一个字符串,没有碰任何真实的日志服务。)", t=tl(S(5)), mark=lidx(S(5), '接收端收到'), done=lidx(S(5), '接收端收到'), kv=KV([['伪造的日志', 'sshd[999] Accepted password for root …'], ['接收端能验证吗', '不能:内容与来源都可伪造'], ['补救', 'TLS + 签名,或本机可信转发']], ['接收端能验证吗'])),
]
A = mkartw('w103', 103, '网络协议,syslog,UDP,日志,RFC 5424,PRI,丢包,真实验证,动画演示',
    '实测 Syslog:PRI = 设施 × 8 + 级别(36 = auth × 8 + warning);RFC 5424 把时间戳 / 主机名 / 结构化数据放进格式;UDP 在 10% / 30% 丢包下收到 456 / 358 条(TCP 全收到);突发 20000 条时接收端丢 79.7%;日志可被轻易伪造。',
    'Syslog 是最古老也最广泛的日志协议:一个 <PRI> 数字、一行文字、一个 UDP 包。它简单到随手一写就能发,也简单到出了问题悄无声息。这篇把格式、优先级的算法、UDP 丢多少、接收端不够快丢多少、以及日志怎么被伪造,逐个在本机量一遍。',
    [('PRI = 设施 × 8 + 级别', '<36> 是 auth(4)× 8 + warning(4)'), ('28.4%', '30% 丢包下 UDP syslog 实际丢失的比例(TCP 为 0)'), ('79.7%', '突发 20000 条时默认缓冲区的接收端丢失的比例')],
    [('PRI 的算法', '<p>PRI = 设施 × 8 + 级别,<36> 是 auth(4)× 8 + warning(4);传统格式没有时间戳和主机名。</p>'),
     ('RFC 5424', '<p>时间戳、主机名、应用名和结构化数据都放进了格式本身。</p>'),
     ('UDP 的丢失', '<p>10% 丢包下 UDP 丢 8.8%,30% 丢 28.4%;TCP 不丢。</p>'),
     ('接收端溢出', '<p>突发 20000 条时默认缓冲区的接收端丢 79.7%,8 KiB 缓冲区丢 98.7%,发送端不知道。</p>'),
     ('没有认证', '<p>任何人可以伪造一条日志,接收端无法验证内容和来源。</p>')],
    steps,
    [ENV_W + '。全部在本机 lo0:发送端是 Python 的 logging.handlers.SysLogHandler(它会在每条报文末尾加 NUL 字节、不带时间戳和主机名);接收端是我写的 UDP / TCP 套接字;第四节接收端每条 sleep 0.5 ms,模拟处理慢;第五节只是向我自己的套接字发一个字符串',
     '没有验证:真实 syslog 守护进程(rsyslog、syslog-ng、macOS 的 unified logging)的行为;RFC 5425 的 TLS syslog;RELP 等带确认的传输;日志长度限制(1024 字节,各实现不同);macOS 本机日志通过 /var/run/syslog 域套接字而不是网络'],
    'Syslog')
